/**
 * Download view - the two desktop builds.
 *
 * Both packages are generated by the running server (server/lib/downloads.js),
 * so whatever you download always matches the arcade you are looking at.  The
 * page explains the difference up front: Lite is a thin window around the
 * website, Host is the whole arcade so you can play and host with no internet.
 */
import { el, btn, pill, toast } from './dom.js';
import { state } from './store.js';
import { api } from './api.js';

/** The arcade we are being served from - baked into the Lite download. */
function here() {
  try {
    return location.origin;
  } catch {
    return '';
  }
}

function fmtSize(bytes) {
  if (!bytes) return '—';
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${Math.round(bytes / 1024)} KB`;
  return `${(bytes / 1048576).toFixed(1)} MB`;
}

function osHint() {
  const ua = navigator.userAgent;
  if (/Windows/i.test(ua)) return 'windows';
  if (/Mac OS X|Macintosh/i.test(ua)) return 'mac';
  if (/Linux|Android/i.test(ua)) return 'linux';
  return 'windows';
}

function stepList(steps) {
  return el('ol', { class: 'steps' }, steps.map((s) => el('li', { text: s })));
}

/**
 * The router reuses one container element and clears it on every render, so
 * "is this still on screen" cannot be answered by looking at the DOM. A render
 * counter does it: any fetch that resolves after a newer mount is ignored.
 */
let renderToken = 0;

export function downloadView(mount) {
  const insideDesktop = !!window.arcade;
  const token = ++renderToken;
  /** False once a newer render replaced us, or the user navigated away. */
  const stillCurrent = () => token === renderToken && !!mount.isConnected;
  const header = el('div', { class: 'card' },
    el('h1', { text: '⬇️ Download the desktop app' }),
    el('p', { class: 'muted', text: insideDesktop
      ? 'You are already running the desktop app. Grab another copy here, or share the link with a friend.'
      : 'Play Memes Arcade in its own window. Two builds: a tiny one that uses this website, and a full one that hosts everything on your computer.' }),
    el('div', { class: 'row' },
      pill('free', 'good'),
      pill('no account needed to download'),
      pill(`built from this server`),
    ),
  );
  mount.appendChild(header);

  const list = el('div', { class: 'grid cards', id: 'download-list' },
    el('div', { class: 'card muted', text: 'Measuring the packages…' }));
  mount.appendChild(list);

  /* the two packages, once the server has measured them */
  api.get(`/api/downloads?server=${encodeURIComponent(here())}`)
    .then((res) => {
      if (!stillCurrent()) return;
      list.replaceChildren(...(res.downloads || []).map((d) => packageCard(d, { insideDesktop })));
      mount.appendChild(el('p', { class: 'muted small', text: `Package v${res.version} · built live by this server, so it always matches. Checksums are on each card.` }));
    })
    .catch((err) => {
      if (!stillCurrent()) return;
      list.replaceChildren(el('div', { class: 'card' },
        el('h3', { text: 'Could not reach the download service' }),
        el('p', { class: 'muted', text: err.message }),
        el('p', { class: 'muted small', text: 'If you are running the server yourself, make sure it is on the latest build.' })));
    });

  /* run instructions */
  const os = osHint();
  const host = el('div', { class: 'card' },
    el('h3', { text: '🏠 Run the Host download (offline play, LAN parties)' }),
    stepList([
      'Install Node.js 18 or newer from nodejs.org (one time).',
      'Unzip the folder anywhere - for example your Desktop.',
      os === 'windows' ? 'Double-click START-HERE.txt to read it, then open a terminal in the folder and run: npm start' : 'Open a terminal in the folder and run: npm start',
      'Open http://localhost:8787 - you are the host now. Friends on your wifi use the "Same wifi" address the server prints.',
      'Want the desktop window instead of a browser tab? Run: cd desktop && npm install && npm start',
    ]),
    el('p', { class: 'muted small', text: 'Zero dependencies for the server itself - npm start works immediately, no npm install needed.' }),
  );
  const lite = el('div', { class: 'card' },
    el('h3', { text: '🪶 Run the Lite download (uses this website)' }),
    stepList([
      'Install Node.js 18 or newer from nodejs.org (one time).',
      'Unzip the folder, then run the included start script:',
      os === 'windows' ? 'run-windows.bat (double-click it)' : 'bash run-mac-linux.sh',
      'The first launch downloads Electron once (~90 MB). After that it opens instantly.',
      'Pick "Connect to a website", confirm the address, and sign in - same account as here.',
    ]),
    el('p', { class: 'muted small', text: 'No server, no game files, no internet-free play - that is what Host is for.' }),
  );
  mount.appendChild(el('div', { class: 'grid two' }, lite, host));

  /* honest comparison */
  mount.appendChild(el('div', { class: 'card' },
    el('h3', { text: 'Which one do I want?' }),
    el('table', { class: 'admin-table' },
      el('thead', {}, el('tr', {}, el('th', { text: '' }), el('th', { text: '🪶 Lite' }), el('th', { text: '🏠 Host' }))),
      el('tbody', {},
        row('Download size', '~30 KB + one-time Electron install', 'the whole arcade (~1 MB of source)'),
        row('Internet needed', 'yes - it loads this website', 'no - runs entirely on your machine'),
        row('Host your own matches', 'no', 'yes, including LAN parties and offline'),
        row('Use the online arcade', 'yes', 'yes, from the Server menu'),
        row('Your account & friends', 'same everywhere', 'same everywhere'),
      ),
    ),
  ));

  /* desktop-app specifics */
  if (insideDesktop) {
    mount.appendChild(el('div', { class: 'card' },
      el('h3', { text: 'You are in the desktop app' }),
      el('p', { class: 'muted', text: 'Switch modes any time from the Server menu: "Connect to a website…" for the online arcade, "Start local server" for offline play. Your saves live in your user folder, so updating never wipes accounts.' }),
      el('div', { class: 'row' },
        btn('Open my saves folder', () => window.arcade?.openFolder?.(), { cls: 'sm' }),
        btn('Copy this download page link', () => {
          const link = `${here()}/?view=download`;
          navigator.clipboard?.writeText(link).then(() => toast('Link copied', 'good'), () => toast(link));
        }, { cls: 'sm' }),
      ),
    ));
  }

  mount.appendChild(el('p', { class: 'muted small', text: 'Everything is MIT licensed and runs locally - no trackers, no telemetry, no account required to try it.' }));
}

function row(label, lite, host) {
  return el('tr', {}, el('td', { text: label }), el('td', { text: lite }), el('td', { text: host }));
}

function packageCard(d, { insideDesktop }) {
  const card = el('div', { class: 'game-card' },
    el('div', { class: 'row spread' },
      el('span', { class: 'icon', text: d.icon }),
      pill(fmtSize(d.size), d.size ? 'good' : 'warn'),
    ),
    el('strong', { text: d.name }),
    el('div', { class: 'muted small', text: d.tagline }),
    el('div', { class: 'meta-line' }, ...d.includes.slice(0, 4).map((i) => pill(i))),
    el('div', { class: 'muted small' },
      el('b', { text: 'Needs: ' }), d.requires.join(' · ')),
    el('div', { class: 'row' },
      btn(`⬇ Download (${fmtSize(d.size)})`, () => {
        const url = d.url || `/api/downloads/${d.id}`;
        toast(`Downloading ${d.filename || d.name}…`, 'good');
        window.open(url, '_blank', 'noopener');
      }, { variant: 'primary' }),
      btn('Copy link', () => {
        const url = `${location.origin}${d.url || `/api/downloads/${d.id}`}`;
        navigator.clipboard?.writeText(url).then(() => toast('Link copied', 'good'), () => toast(url));
      }, { cls: 'sm' }),
    ),
    el('div', { class: 'muted small mono', text: d.note }),
    d.sha256 ? el('div', { class: 'muted small mono', text: `sha256 ${d.sha256.slice(0, 32)}…`, title: d.sha256 }) : null,
  );
  return card;
}
